#!/bin/sh
# Turns the names in names.mk (passed in the environment by the Makefile)
# into Go or C source. Usage: gen-names.sh go|c
set -eu

case "${1-}" in
go)
    cat <<EOF
// Code generated by scripts/gen-names.sh from names.mk; DO NOT EDIT.

// Package names holds the project's names. They are defined once, in
// names.mk; run \`make gen\` after changing them.
package names

const (
	Name          = "$NAME"
	Module        = "$MODULE"
	EnvPrefix     = "$ENV_PREFIX"
	Lib           = "$LIB"
	ExtID         = "$EXT_ID"
	ExtBranch     = "$EXT_BRANCH"
	Mount         = "$MOUNT"
	CompatName    = "$COMPAT_NAME"
	CacheCwd      = "$CACHE_CWD"
	CacheHost     = "$CACHE_HOST"
	CacheNone     = "$CACHE_NONE"
	HostPathCache = "$HOST_PATH_CACHE"

	ModeProbe  = "$MODE_PROBE"
	ModeExec   = "$MODE_EXEC"
	ModeLookup = "$MODE_LOOKUP"
	ModeShell  = "$MODE_SHELL"
	ModeSocket = "$MODE_SOCKET"
	ModeAgent  = "$MODE_AGENT"
)

// Version is set at build time with -ldflags -X.
var Version = "dev"

// Env returns the name of one of the project's environment variables.
func Env(suffix string) string { return EnvPrefix + "_" + suffix }
EOF
    ;;
c)
    cat <<EOF
/* Generated by scripts/gen-names.sh from names.mk; do not edit. */
#ifndef FPS_NAMES_H
#define FPS_NAMES_H
#define FPS_NAME "$NAME"
#define FPS_ENV_PREFIX "$ENV_PREFIX"
#define FPS_ENV(suffix) FPS_ENV_PREFIX "_" suffix
#define FPS_LIB "$LIB"
#define FPS_MOUNT "$MOUNT"
#define FPS_HELPER FPS_MOUNT "/bin/" FPS_NAME
#define FPS_CACHE_CWD_DIR "$CACHE_CWD"
#define FPS_CACHE_HOST_DIR "$CACHE_HOST"
#define FPS_CACHE_NONE_DIR "$CACHE_NONE"
#define FPS_MODE_EXEC "$MODE_EXEC"
#define FPS_MODE_LOOKUP "$MODE_LOOKUP"
#define FPS_MODE_SHELL "$MODE_SHELL"
#define FPS_MODE_SOCKET "$MODE_SOCKET"
#endif
EOF
    ;;
*)
    echo "usage: $0 go|c" >&2
    exit 2
    ;;
esac
